// Some portions generated by Claude.
package io.github.djclarke.eclipselink.mcp;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;

/**
 * Every source and config file carries the project header (template: {@code etc/copyright-header.txt}),
 * in the comment syntax of its file type. Files that are generated output are exempt: the {@code init}
 * output of {@code samples/sales-db-generated}. See CONTRIBUTING.md.
 */
class LicenseHeaderTest {

    static final List<String> REQUIRED = List.of(
            "Copyright (c) 2026 Doug Clarke.",
            "SPDX-License-Identifier: EPL-2.0 OR BSD-3-Clause",
            "Some portions generated by Claude.");

    @Test
    void sourceAndConfigFilesHaveHeader() throws IOException {
        List<Path> files = new java.util.ArrayList<>(List.of(Path.of("pom.xml")));
        try (Stream<Path> s = Stream.concat(Files.walk(Path.of("src")), Files.walk(Path.of("samples")))) {
            s.filter(Files::isRegularFile).filter(LicenseHeaderTest::needsHeader).forEach(files::add);
        }
        List<String> missing = files.stream()
                .filter(f -> !hasHeader(f))
                .map(Path::toString)
                .sorted()
                .toList();
        assertEquals(List.of(), missing, "Files without the header from etc/copyright-header.txt");
    }

    static boolean needsHeader(Path f) {
        String p = f.toString().replace('\\', '/');
        if (p.startsWith("samples/sales-db-generated/")) {
            return false;
        }
        return p.startsWith("src/test/resources/META-INF/services/")
                || p.endsWith(".java") || p.endsWith(".xml") || p.endsWith(".yaml") || p.endsWith(".sql");
    }

    static boolean hasHeader(Path f) {
        try {
            String head = String.join("\n", Files.readAllLines(f).stream().limit(20).toList());
            return REQUIRED.stream().allMatch(head::contains);
        } catch (IOException e) {
            return false;
        }
    }
}
